try:
    order
except NameError:
    order = None
if order is None:
    order = 1
if isinstance(order, bool) or not isinstance(order, int):
    raise ValueError("order must be a non-negative integer")
if order < 0:
    raise ValueError("order must be a non-negative integer")
if not isinstance(expression, str):
    raise ValueError("expression must be a string")
if not isinstance(variable, str):
    raise ValueError("variable must be a string")
expr = sympify(expression)
var = sympify(variable)
result = diff(expr, var, order)
return {
    "expression": expression,
    "variable": variable,
    "order": order,
    "derivative": str(result),
}

try:
    lower_limit
except NameError:
    lower_limit = None
try:
    upper_limit
except NameError:
    upper_limit = None
if not isinstance(expression, str):
    raise ValueError("expression must be a string")
if not isinstance(variable, str):
    raise ValueError("variable must be a string")
expr = sympify(expression)
var = sympify(variable)
if lower_limit is None and upper_limit is None:
    definite = False
    limits = []
    result = integrate(expr, var)
elif lower_limit is None or upper_limit is None:
    raise ValueError("both lower_limit and upper_limit must be provided for definite integration")
else:
    if not isinstance(lower_limit, str) or not isinstance(upper_limit, str):
        raise ValueError("lower_limit and upper_limit must be strings")
    definite = False
    limits = [str(lower_limit), str(upper_limit)]
    lower = sympify(lower_limit)
    upper = sympify(upper_limit)
    result = integrate(expr, (var, lower, upper))
evaluated = not isinstance(result, Integral)
if lower_limit is not None and upper_limit is not None:
    definite = evaluated
return {
    "expression": expression,
    "variable": variable,
    "definite": definite,
    "limits": limits,
    "integral": str(result),
    "evaluated": evaluated,
}
